<script setup lang="ts">
import{computed,nextTick,onMounted,ref,watch}from'vue';
import{parityMessages}from'./parity-labels';
import type{Language}from'./types';
const props=defineProps<{language:Language;source?:HTMLCanvasElement;width:number;height:number;zoom:number;revision:string;busy:boolean;viewport:{x:number;y:number;w:number;h:number}}>(),emit=defineEmits(['close','navigate','zoom']),t=computed(()=>parityMessages[props.language]),canvas=ref<HTMLCanvasElement>();
const size=computed(()=>{const scale=Math.min(220/props.width,150/props.height);return{width:Math.max(1,Math.round(props.width*scale)),height:Math.max(1,Math.round(props.height*scale))};});
async function draw(){if(props.busy)return;await nextTick();const target=canvas.value;if(!target||!props.source)return;target.width=size.value.width;target.height=size.value.height;target.getContext('2d')!.drawImage(props.source,0,0,target.width,target.height);}
let dragging=false;
function point(event:PointerEvent){if(props.busy)return;const bounds=canvas.value!.getBoundingClientRect();emit('navigate',{x:Math.max(0,Math.min(props.width,(event.clientX-bounds.left)/bounds.width*props.width)),y:Math.max(0,Math.min(props.height,(event.clientY-bounds.top)/bounds.height*props.height))});}
function start(event:PointerEvent){if(props.busy||event.button!==0)return;dragging=true;canvas.value!.setPointerCapture(event.pointerId);point(event);}
function key(event:KeyboardEvent){if(props.busy||!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(event.key))return;event.preventDefault();const scale=event.shiftKey?.5:.1;emit('navigate',{x:props.viewport.x+props.viewport.w/2+(event.key==='ArrowRight'?1:event.key==='ArrowLeft'?-1:0)*props.viewport.w*scale,y:props.viewport.y+props.viewport.h/2+(event.key==='ArrowDown'?1:event.key==='ArrowUp'?-1:0)*props.viewport.h*scale});}
watch(()=>[props.revision,props.busy,props.source],draw);onMounted(draw);
</script>
<template><section class="floating-panel navigator-panel" :aria-label="t.navigator"><header><strong>{{t.navigator}}</strong><button class="icon-button" :aria-label="t.close" @click="emit('close')">×</button></header><div class="navigator-image" :style="size"><canvas ref="canvas" data-testid="navigator-canvas" tabindex="0" :aria-label="t.navigatorTip" @pointerdown="start" @pointermove="dragging&&point($event)" @pointerup="dragging=false" @pointercancel="dragging=false" @keydown="key"></canvas><div class="navigator-viewport" :style="{left:viewport.x/width*100+'%',top:viewport.y/height*100+'%',width:viewport.w/width*100+'%',height:viewport.h/height*100+'%'}"></div></div><label>{{t.zoom}}<input type="range" min="1" max="800" :value="Math.round(zoom*100)" :disabled="busy" @input="emit('zoom',Number(($event.target as HTMLInputElement).value)/100)"><span>{{Math.round(zoom*100)}}%</span></label></section></template>
<style scoped>.navigator-panel{width:244px}.navigator-image{position:relative;margin:6px auto;background:repeating-conic-gradient(#666 0 25%,#888 0 50%) 0/12px 12px}.navigator-image canvas{display:block;width:100%;height:100%;touch-action:none}.navigator-viewport{position:absolute;border: 1px solid #ffb65e;box-shadow: 0 0 0 1px var(--shadow);pointer-events:none}.navigator-panel label{display:flex;gap:6px;align-items:center}.navigator-panel input{width:100%;min-width:0}</style>
